"""Generate the panel's TypeScript types from the contract's JSON Schema.

A small, deterministic translator for the subset of JSON Schema pydantic emits for the
contract: ``$ref``, ``oneOf``/``anyOf``, ``const``, ``enum``, arrays, objects with
properties or ``additionalProperties``, the scalar types and the empty schema (JSON).
Anything else raises, so a new construct cannot be silently mistranslated.
"""

from __future__ import annotations

import json
from collections.abc import Mapping, Sequence
from typing import Final

HEADER: Final = (
    "// Generated by `make contract` (python -m sandcage.contract) from\n"
    "// src/sandcage/contract. Do not edit by hand: edit the Python models and regenerate.\n"
)
_JSON_VALUE: Final = (
    "export type JsonValue =\n"
    "  | string\n"
    "  | number\n"
    "  | boolean\n"
    "  | null\n"
    "  | JsonValue[]\n"
    "  | { [key: string]: JsonValue };\n"
)
_SCALARS: Final = {"string": "string", "integer": "number", "number": "number"}
_SCALARS_MORE: Final = {"boolean": "boolean", "null": "null"}
# Keywords that carry no type information, or that the branches below translate.
_KNOWN_KEYS: Final = frozenset(
    {
        "$ref", "oneOf", "anyOf", "discriminator", "const", "enum", "type", "items",
        "properties", "required", "additionalProperties", "title", "description", "default",
    }
)  # fmt: skip


class SchemaTranslationError(ValueError):
    """The schema uses a construct this translator does not know."""


def to_typescript(
    schema: Mapping[str, object],
    *,
    root_name: str,
    constants: Mapping[str, Sequence[str]],
) -> str:
    defs = schema.get("$defs", {})
    if not isinstance(defs, Mapping):
        raise SchemaTranslationError("$defs must be an object")
    parts = [HEADER, _JSON_VALUE]
    for name in sorted(defs):
        if name == "JsonValue":
            continue
        parts.append(_declaration(name, defs[name]))
    root = {key: value for key, value in schema.items() if key not in {"$defs", "$schema"}}
    parts.append(f"export type {root_name} = {_type(root)};\n")
    parts.append(f'export type {root_name}Kind = {root_name}["kind"];\n')
    for const_name, values in constants.items():
        items = ", ".join(json.dumps(value) for value in values)
        parts.append(f"export const {const_name} = [{items}] as const;\n")
    return "\n".join(parts)


def _declaration(name: str, schema: object) -> str:
    if not isinstance(schema, Mapping):
        raise SchemaTranslationError(f"{name}: a definition must be an object")
    doc = _doc(schema.get("description"), indent="")
    if schema.get("type") == "object" and "properties" in schema:
        return f"{doc}export interface {name} {{\n{_members(name, schema)}}}\n"
    return f"{doc}export type {name} = {_type(schema)};\n"


def _members(name: str, schema: Mapping[str, object]) -> str:
    properties = schema["properties"]
    required = schema.get("required", [])
    if not isinstance(properties, Mapping) or not isinstance(required, list):
        raise SchemaTranslationError(f"{name}: malformed properties")
    lines = []
    for prop, prop_schema in properties.items():
        if not isinstance(prop_schema, Mapping):
            raise SchemaTranslationError(f"{name}.{prop}: malformed property")
        optional = "" if prop in required else "?"
        lines.append(
            f"{_doc(prop_schema.get('description'), indent='  ')}"
            f"  {prop}{optional}: {_type(prop_schema)};\n"
        )
    return "".join(lines)


def _type(schema: object) -> str:
    if not isinstance(schema, Mapping):
        raise SchemaTranslationError(f"not a schema: {schema!r}")
    unknown = set(schema) - _KNOWN_KEYS
    if unknown:
        raise SchemaTranslationError(f"unsupported keywords {sorted(unknown)}")
    if "$ref" in schema:
        ref = schema["$ref"]
        if not isinstance(ref, str) or not ref.startswith("#/$defs/"):
            raise SchemaTranslationError(f"unsupported $ref {ref!r}")
        return ref.removeprefix("#/$defs/")
    for key in ("oneOf", "anyOf"):
        if key in schema:
            options = schema[key]
            if not isinstance(options, list) or not options:
                raise SchemaTranslationError(f"{key} must be a non-empty list")
            return " | ".join(_type(option) for option in options)
    if "const" in schema:
        return json.dumps(schema["const"])
    if "enum" in schema:
        values = schema["enum"]
        if not isinstance(values, list) or not values:
            raise SchemaTranslationError("enum must be a non-empty list")
        return " | ".join(json.dumps(value) for value in values)
    kind = schema.get("type")
    if kind == "array":
        item = _type(schema.get("items", {}))
        return f"({item})[]" if " | " in item else f"{item}[]"
    if kind == "object":
        if "properties" in schema:
            raise SchemaTranslationError("inline objects with properties need a definition")
        extra = schema.get("additionalProperties", {})
        return f"{{ [key: string]: {_type(extra) if extra else 'JsonValue'} }}"
    if isinstance(kind, str) and kind in _SCALARS:
        return _SCALARS[kind]
    if isinstance(kind, str) and kind in _SCALARS_MORE:
        return _SCALARS_MORE[kind]
    if kind is None and not set(schema) - {"title", "description", "default"}:
        return "JsonValue"
    raise SchemaTranslationError(f"unsupported schema {dict(schema)!r}")


def _doc(text: object, *, indent: str) -> str:
    if not isinstance(text, str) or not text.strip():
        return ""
    lines = [line.rstrip().replace("*/", "*\\/") for line in text.strip().splitlines()]
    body = "".join(f"{indent} * {line}\n" if line else f"{indent} *\n" for line in lines)
    return f"{indent}/**\n{body}{indent} */\n"
